# --- your code ---
def max_path_sum(root: "TreeNode") -> int:
    best = root.val

    def gain(node: "TreeNode | None") -> int:
        """Largest sum of a path that starts at `node` and only goes down."""
        nonlocal best
        if node is None:
            return 0
        left = max(gain(node.left), 0)              # a negative branch is better left out
        right = max(gain(node.right), 0)
        best = max(best, node.val + left + right)   # the path that bends at this node
        return node.val + max(left, right)          # a parent can extend one side only

    gain(root)
    return best


